<script setup lang="ts">import { computed } from 'vue'; import { useRoute } from 'vue-router'; import { useExamStore } from '../stores/exam'; const route=useRoute(),store=useExamStore(),testId=String(route.params.testId); const result=computed(()=>store.latestResults[testId]); const scoreClass=(n:number)=>n>=80?'great':n>=60?'good':'build'</script>
<template><div class="page narrow"><template v-if="result"><p class="eyebrow">Test complete</p><h1>Your raw score</h1><div class="result-hero" :class="scoreClass(result.accuracy)"><div class="score-ring"><strong>{{ result.accuracy }}%</strong><span>accuracy</span></div><div><p>{{ result.total.correct }} correct out of {{ result.total.total }}</p><h2>Keep building momentum.</h2><p>Raw score is shown because the official TOEIC scaled score is not a simple linear conversion.</p></div></div><div class="score-grid"><article><span>Listening</span><strong>{{ result.listening.correct }} / {{ result.listening.total }}</strong></article><article><span>Reading</span><strong>{{ result.reading.correct }} / {{ result.reading.total }}</strong></article><article><span>Total</span><strong>{{ result.total.correct }} / {{ result.total.total }}</strong></article></div><h2 class="subheading">Part breakdown</h2><div class="part-results"><div v-for="score in result.partScores" :key="score.part"><span>Part {{ score.part }}</span><div class="progress"><i :style="{width:`${score.total?score.correct/score.total*100:0}%`}"/></div><strong>{{ score.correct }} / {{ score.total }}</strong></div></div><div class="hero-actions"><RouterLink class="button primary" :to="`/test/${testId}/review`">Review answers</RouterLink><RouterLink class="button" :to="`/test/${testId}/practice?wrong=1`">Practice wrong answers</RouterLink></div></template><div v-else class="empty-state"><h1>No result yet</h1><p>Complete and submit a test first.</p><RouterLink class="button primary" :to="`/test/${testId}`">Go to test</RouterLink></div></div></template>
